/**
 * Built-in sample datasets.
 *
 * The CSVs live in /static/samples and are generated by scripts/make-samples.mjs. They are
 * fetched on demand (not bundled) so the landing page stays light, and each one carries
 * deliberate quality problems so the cleaning screen has real work to do.
 */

import type { Dataset } from '../types';
import { buildDataset } from '../analysis/stats';
import { parseCsvText } from './parse';
import { asset } from '$app/paths';
import type { AssetPath } from '$app/types';

export type SampleId = 'sales' | 'hr' | 'students' | 'churn';

/** `AssetPath` keeps these literal, so a renamed sample CSV is a compile error. */
type SampleAsset = AssetPath & `samples/${string}`;

export type SampleDataset = {
	id: SampleId;
	name: string;
	file: SampleAsset;
	tagline: string;
	description: string;
	rows: number;
	columns: number;
	/** What the dashboard will show, so the user knows what to expect before clicking. */
	highlights: string[];
	icon: 'cart' | 'people' | 'graduation' | 'churn';
};

export const SAMPLES: SampleDataset[] = [
	{
		id: 'sales',
		name: 'Retail Sales',
		file: 'samples/sales.csv',
		tagline: '18 months of order lines',
		description:
			'Order-level sales for a home & kitchen retailer across 5 regions and 4 channels, from January 2024 to June 2025.',
		rows: 6561,
		columns: 14,
		highlights: ['Diwali peak and a March slump', 'Region and channel comparison', 'Profit vs revenue correlation'],
		icon: 'cart'
	},
	{
		id: 'hr',
		name: 'HR / Employees',
		file: 'samples/hr-employees.csv',
		tagline: '486 employee records',
		description:
			'Headcount, pay bands, tenure, performance and attrition across 7 departments and 7 locations.',
		rows: 486,
		columns: 16,
		highlights: ['Salary spread by department', 'Attrition against satisfaction', 'A visible gender pay gap'],
		icon: 'people'
	},
	{
		id: 'students',
		name: 'Student Performance',
		file: 'samples/student-performance.csv',
		tagline: '620 student results',
		description:
			'Subject marks, attendance, study hours and home environment for classes 9 to 12 across four streams.',
		rows: 620,
		columns: 19,
		highlights: ['Attendance drives marks', 'Grade distribution', 'Stream-by-stream comparison'],
		icon: 'graduation'
	},
	{
		id: 'churn',
		name: 'Customer Churn',
		file: 'samples/customer-churn.csv',
		tagline: '911 SaaS subscriptions',
		description:
			'Subscription plans, contract length, engagement, support load and churn outcome for a B2B software product.',
		rows: 911,
		columns: 16,
		highlights: ['Month-to-month churns hardest', 'Spend by plan', 'Tickets vs NPS'],
		icon: 'churn'
	}
];

export function findSample(id: string): SampleDataset | undefined {
	return SAMPLES.find((s) => s.id === id);
}

/** Fetch + parse + type a sample dataset. */
export async function loadSample(id: SampleId): Promise<Dataset> {
	const sample = findSample(id);
	if (!sample) throw new Error(`Unknown sample dataset "${id}".`);
	const response = await fetch(asset(sample.file));
	if (!response.ok) {
		throw new Error(`Could not load the ${sample.name} sample (${response.status}).`);
	}
	const text = await response.text();
	const outcome = await parseCsvText(text);
	return buildDataset(outcome.table, { name: sample.name, source: 'sample' });
}
